VID.narration = {"look":{"bar":false},"scenes":[{"dur":7.616,"caps":[[0.5,6.59,"Algorithms, phase one. Foundations and PageRank. This is how Google ranked the web."]],"warp":[[0,0],[0.5,0.9],[7.616,4]]},{"dur":18.344,"caps":[[0.5,5.07,"“Find the biggest” is only a wish."],[5.32,12.53,"An algorithm answers every question in advance."],[12.78,17.43,"Even: what if the list is empty?"]],"warp":[[0,0],[0.5,0.4],[5.32,2.5],[12.78,8],[18.344,10.3]]},{"dur":21.687,"caps":[[0.5,4.99,"Scan once and keep the biggest so far."],[5.24,9.57,"After k items, best is the biggest of those k."],[9.82,16.63,"It stays true after every step: the invariant."],[16.88,20.97,"At the end the promise is the answer: 9."]],"warp":[[0,0],[0.5,0.4],[5.24,2.8],[9.82,6],[16.88,10.3],[21.687,12.3]]},{"dur":28.422,"caps":[[0.5,6.19,"Each square is one work() call. One loop: 8."],[6.44,13.33,"The inner loop grows: 0 + 1 + 2 + … + 7 = 28."],[13.58,20.23,"Let it run to n instead: 8 × 8 = 64."],[20.48,26.41,"Halving: 8, 4, 2, 1 is only 3 calls."]],"warp":[[0,0],[0.5,0.4],[6.44,3.4],[13.58,7],[20.48,9.8],[28.422,13]]},{"dur":30.023,"caps":[[0.5,3.71,"Now double n, from 8 to 16."],[3.96,8.13,"One loop: twice the work."],[8.38,13.35,"Nested loops: four times the work."],[13.6,19.93,"Growing inner loop: 28 to 120, about ×4."],[20.18,25.15,"Halving: just one extra call."],[25.4,28.05,"The shape of the growth is the Big-O."]],"warp":[[0,0],[0.5,0.4],[3.96,2.9],[8.38,5],[13.6,7.6],[20.18,9.6],[25.4,11.9],[30.023,13.6]]},{"dur":33.205,"caps":[[0.5,6.03,"Pages link to pages."],[6.28,11.01,"Give every page 25 tokens of rank."],[11.26,15.43,"Each page pours its tokens down its links."],[15.68,22.33,"D has no links, so its 25 tokens vanish."],[22.58,27.95,"Fix: a dead end pours to every page."],[28.2,32.05,"Now nothing is lost: the total is 100 again."]],"warp":[[0,0],[0.5,0.4],[6.28,2.3],[11.26,4.3],[15.68,6.6],[22.58,8.9],[28.2,12.2],[33.205,14.7]]},{"dur":18.343,"caps":[[0.5,5.15,"A and B link only to each other."],[5.4,9.49,"Rank sloshes between them, round after round."],[9.74,13.75,"X is starved; A and B just swap the lead."],[14,17.21,"What if the rank could jump anywhere?"]],"warp":[[0,0],[0.5,0.4],[5.4,2.8],[9.74,6.2],[14,8.2],[18.343,10]]},{"dur":26.657,"caps":[[0.5,4.99,"The surfer follows a link 85% of the time."],[5.24,8.61,"Otherwise it teleports to a random page."],[8.86,12.23,"Count the visits over many hops."],[12.48,19.13,"The shares settle: that is PageRank."],[19.38,25.31,"X is no longer starved: 5%, by teleporting."]],"warp":[[0,0],[0.5,0.4],[5.24,3.2],[8.86,6.9],[12.48,9.6],[19.38,11.1],[26.657,13]]},{"dur":20.108,"caps":[[0.5,6.11,"Each column is where one page sends its rank."],[6.36,12.53,"T's column sums to 0, so T pours 0.2 to all."],[12.78,19.27,"Teleport: × 0.85, then add 0.15 ÷ 5 = 0.03."]],"warp":[[0,0],[0.5,0.4],[6.36,5.2],[12.78,8.5],[20.108,12.6]]},{"dur":19.9,"caps":[[0.5,5.07,"Start with equal rank on every page."],[5.32,8.77,"Each round: multiply by the matrix."],[9.02,12.95,"Early rounds swing, then the ranks settle."],[13.2,18.41,"R ranks first. The same loop ranks billions."]],"warp":[[0,0],[0.5,0.4],[5.32,2.2],[9.02,5.8],[13.2,9],[19.9,12]]},{"dur":15.418,"caps":[],"warp":[[0,0],[0.5,0.9],[3.96,2],[9.34,3.1],[15.418,9]]}]};
